// ===== CONFIGURACIÓN DE LABORATORIO (editar antes de activar) =====
// Todos los correos van a este destinatario de prueba, NO al paciente: los datos del laboratorio son sintéticos.
const LAB_RECIPIENT = 'LAB_RECIPIENT_AQUI';
// ====================================================================
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// El backend envia hora local de Bogota SIN zona horaria: se muestra tal cual, sin convertir.
const fmt = (iso) => { const s = String(iso); const conZona = /[zZ]$|[+-]d{2}:?d{2}$/.test(s); const d = new Date(conZona ? s : s + 'Z'); return isNaN(d) ? esc(iso) : d.toLocaleString('es-CO', { timeZone: conZona ? 'America/Bogota' : 'UTC', dateStyle: 'full', timeStyle: 'short' }); };
const MENSAJES = {
  ESPECIALIZADA_APROBADA: { asunto: 'Tu cita especializada fue aprobada', frase: 'Tu solicitud de cita especializada fue APROBADA.' },
  ESPECIALIZADA_RECHAZADA: { asunto: 'Tu cita especializada fue rechazada', frase: 'Tu solicitud de cita especializada fue RECHAZADA.' },
  CITA_CANCELADA: { asunto: 'Tu cita fue cancelada', frase: 'Tu cita fue CANCELADA.' },
  REPROGRAMACION_APROBADA: { asunto: 'Tu reprogramación fue aprobada', frase: 'Tu solicitud de reprogramación fue APROBADA.' },
  REPROGRAMACION_RECHAZADA: { asunto: 'Tu reprogramación fue rechazada', frase: 'Tu solicitud de reprogramación fue RECHAZADA.' },
};
const entrada = $input.first().json;
const b = entrada.body ?? entrada;
const fallo = (httpStatus, error) => [{ json: { ok: false, httpStatus, error } }];

if (!b || typeof b !== 'object') return fallo(400, 'Cuerpo vacío o inválido');
if (!MENSAJES[b.tipo]) return fallo(400, 'Tipo de evento desconocido: ' + esc(b.tipo));
if (!Number.isInteger(b.citaId)) return fallo(400, 'citaId inválido');
if (!b.pacienteEmail || !String(b.pacienteEmail).includes('@')) return fallo(400, 'Falta pacienteEmail');
if (LAB_RECIPIENT === 'LAB_RECIPIENT_AQUI') return fallo(503, 'Destinatario de laboratorio sin configurar');

const m = MENSAJES[b.tipo];
const motivo = b.motivo ? '<p><b>Motivo:</b> ' + esc(b.motivo) + '</p>' : '';
const html = '<p>Hola ' + esc(b.pacienteNombre ?? '') + ',</p><p>' + m.frase + '</p>'
  + '<ul><li><b>Cita:</b> #' + b.citaId + '</li>'
  + '<li><b>Fecha:</b> ' + fmt(b.inicio) + '</li>'
  + '<li><b>Profesional:</b> ' + esc(b.profesionalNombre) + '</li>'
  + '<li><b>Especialidad:</b> ' + esc(b.especialidadNombre) + '</li>'
  + '<li><b>Sede:</b> ' + esc(b.sedeNombre) + '</li></ul>' + motivo
  + '<p style="color:#666">Correo de laboratorio (datos sintéticos). Destinatario original: ' + esc(b.pacienteEmail) + '</p>';
return [{ json: { ok: true, tipo: b.tipo, citaId: b.citaId, to: LAB_RECIPIENT, subject: '[FCV Lab] ' + m.asunto + ' (cita #' + b.citaId + ')', html } }];
